(function() {
    'use strict';

    class FrontierAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Embrace the Unknown`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Concept Numbers Reference Card.
            this.BUDGET_CAP = 6;        // EUR 6M discretionary war chest
            this.START_MONTHS = 9;      // 9 months to FY2027 lock / board review
            this.PIVOT_COST = 40;       // EUR 40M full pivot

            // Probe economics: cost (EUR M), weeks consumed, and belief-change power.
            // Cheap, sharp, walk-away-able probes are efficient; the big build is a sunk-cost trap.
            this.PROBES = {
                fakedoor:  { cost: 0.05, weeks: 3,  power: 16, walkaway: true,  paysignal: true  },
                retailer:  { cost: 0.20, weeks: 6,  power: 18, walkaway: true,  paysignal: false },
                pilot:     { cost: 0.40, weeks: 10, power: 22, walkaway: true,  paysignal: true  },
                acquihire: { cost: 1.50, weeks: 14, power: 20, walkaway: true,  paysignal: false },
                bigbuild:  { cost: 1.20, weeks: 26, power: 14, walkaway: false, paysignal: false }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    resolved: 5,
                    option: 50,
                    conviction: 10,
                    budgetUsed: 0,
                    monthsLeft: 9,
                    framingHeld: ``,
                    probesPicked: [],
                    bigbuildLocked: false,
                    forcedParalysis: false,
                    falsePrecision: false,
                    committed: ``,
                    resolvedHistory: [5],
                    optionHistory: [50],
                    convictionHistory: [10],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    nature: `uncertainty`,
                    reframe: `openecosystem`,
                    assumption: `willingtopay`,
                    candor: 60,
                    probes: [],
                    discipline: `precommit`,
                    evidence: `honest`,
                    optionset: `staged`,
                    remaining: 50,
                    timing: `stagednow`,
                    size: `small`,
                    trigger: `paymilestone`,
                    stand: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const nat = document.getElementById(`natureInput`);
                const ref = document.getElementById(`reframeInput`);
                const asm = document.getElementById(`assumptionInput`);
                const cand = document.getElementById(`candorInput`);
                if (nat) decisions.nature = nat.value;
                if (ref) decisions.reframe = ref.value;
                if (asm) decisions.assumption = asm.value;
                if (cand) decisions.candor = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const ids = [
                    [`probeFakedoor`, `fakedoor`], [`probeRetailer`, `retailer`], [`probePilot`, `pilot`],
                    [`probeAcquihire`, `acquihire`], [`probeBigbuild`, `bigbuild`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.probes = picked;
                const disc = document.getElementById(`disciplineInput`);
                if (disc) decisions.discipline = disc.value;
                if (picked.length < 1) {
                    warn(`warn_probe_none`); return false;
                }
                let cost = 0;
                picked.forEach((p) => { cost += this.PROBES[p].cost; });
                const remaining = this.BUDGET_CAP - state.domainState.budgetUsed;
                if (cost > remaining + 0.0001) {
                    warn(`warn_over_budget`); return false;
                }
            } else if (round === 3) {
                const ev = document.getElementById(`evidenceInput`);
                const os = document.getElementById(`optionsetInput`);
                const rem = document.getElementById(`remainingInput`);
                if (ev) decisions.evidence = ev.value;
                if (os) decisions.optionset = os.value;
                if (rem) decisions.remaining = parseInt(rem.value, 10);
                if (!Number.isFinite(decisions.remaining) || decisions.remaining < 0 || decisions.remaining > 100) {
                    warn(`warn_remaining_range`); return false;
                }
            } else if (round === 4) {
                const tm = document.getElementById(`timingInput`);
                const sz = document.getElementById(`sizeInput`);
                const tg = document.getElementById(`triggerInput`);
                const st = document.getElementById(`standInput`);
                if (tm) decisions.timing = tm.value;
                if (sz) decisions.size = sz.value;
                if (tg) decisions.trigger = tg.value;
                if (st) decisions.stand = parseInt(st.value, 10);
                if (!Number.isFinite(decisions.stand) || decisions.stand < 0 || decisions.stand > 100) {
                    warn(`warn_stand_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let resolvedDelta = 0, optionDelta = 0, convictionDelta = 0;
            let spend = 0, weeksUsed = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // THE REFRAME. Distinguish risk from uncertainty (Knightian); convert threat to
                // a generative opportunity framing; name the make-or-break assumption; hold it as a
                // hypothesis, not a belief. Common Errors 1 & 3 punished here.
                if (d.nature === `uncertainty`) {
                    convictionDelta += 16; optionDelta += 6; coachKey = `coach_r1_uncertainty`;
                } else if (d.nature === `risk`) {
                    // False precision — treating genuine uncertainty as measurable risk.
                    convictionDelta -= 14; ds.falsePrecision = true; coachKey = `coach_r1_risk`;
                } else if (d.nature === `nothing`) {
                    // Paralysis dressed as patience.
                    convictionDelta -= 10; optionDelta -= 6; coachKey = `coach_r1_nothing`;
                }

                if (d.reframe === `openecosystem` || d.reframe === `servicelayer`) {
                    optionDelta += 12; convictionDelta += 6; ds.framingHeld = d.reframe;
                    if (d.nature === `uncertainty`) coachKey = `coach_r1_reframe_good`;
                } else if (d.reframe === `defend`) {
                    optionDelta -= 8; convictionDelta -= 4; ds.framingHeld = d.reframe; coachKey = `coach_r1_defend`;
                } else if (d.reframe === `ignore`) {
                    optionDelta -= 12; convictionDelta -= 6; ds.framingHeld = d.reframe; coachKey = `coach_r1_ignore`;
                }

                // The right assumption to name is the one a cheap probe can actually test.
                if (d.assumption === `willingtopay`) { convictionDelta += 10; coachKey = (d.nature === `uncertainty` && (d.reframe === `openecosystem` || d.reframe === `servicelayer`)) ? `coach_r1_sharp` : coachKey; }
                else if (d.assumption === `none`) { convictionDelta -= 10; coachKey = `coach_r1_noassumption`; }
                else { convictionDelta += 2; }

                if (d.candor >= 60) { convictionDelta += 8; optionDelta += 2; }
                else if (d.candor <= 25) { convictionDelta -= 8; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.nature === `uncertainty` && (d.reframe === `openecosystem` || d.reframe === `servicelayer`) && d.assumption === `willingtopay`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // BUY INFORMATION CHEAPLY. Probe portfolio: belief-change per euro, time-boxed,
                // cheap enough to walk away from. Common Errors 2 & 4 punished here.
                const picks = d.probes || [];
                ds.probesPicked = picks.slice();
                let power = 0, anyPaySignal = false, hasSunkCost = false, allWalkaway = true;
                picks.forEach((p) => {
                    const pr = this.PROBES[p];
                    spend += pr.cost; weeksUsed += pr.weeks; power += pr.power;
                    if (pr.paysignal) anyPaySignal = true;
                    if (!pr.walkaway) { hasSunkCost = true; allWalkaway = false; }
                });

                // Diversifying across cheap, sharp probes (incl. a willingness-to-pay signal) resolves
                // the most uncertainty per euro. Efficiency = belief power divided by spend.
                const efficiency = spend > 0 ? power / (spend + 0.3) : 0;
                resolvedDelta += Math.round(power * 0.55);
                if (anyPaySignal) { resolvedDelta += 6; convictionDelta += 4; }

                // Sunk-cost probe (the six-month build): too expensive to walk away from, so it forces
                // commitment regardless of result and erodes the very optionality probing should buy.
                if (hasSunkCost) {
                    optionDelta -= 16; convictionDelta -= 10; ds.bigbuildLocked = true;
                    coachKey = `coach_r2_sunkcost`;
                } else if (efficiency >= 30 && picks.length >= 2) {
                    optionDelta += 10; convictionDelta += 8; coachKey = `coach_r2_efficient`;
                } else if (picks.length >= 2) {
                    optionDelta += 6; convictionDelta += 4; coachKey = `coach_r2_portfolio`;
                } else {
                    optionDelta += 3; coachKey = `coach_r2_single`;
                }

                // The acqui-hire alone is real learning but pricey for the belief it moves.
                if (picks.length === 1 && picks[0] === `acquihire`) { convictionDelta -= 4; coachKey = `coach_r2_expensive`; }

                // Probe discipline: a pre-committed kill rule keeps probes cheap to abandon.
                if (d.discipline === `precommit`) { convictionDelta += 10; optionDelta += 4; }
                else if (d.discipline === `confirm`) {
                    // Probes designed to confirm can't change your mind (Common Error 4 + confirmation).
                    convictionDelta -= 12; resolvedDelta = Math.round(resolvedDelta * 0.6); ds.falsePrecision = true; coachKey = `coach_r2_confirm`;
                } else if (d.discipline === `seehow`) { convictionDelta -= 3; }

                summaryKey = (!hasSunkCost && anyPaySignal && d.discipline === `precommit`) ? `sum_r2_good` : (hasSunkCost ? `sum_r2_sunk` : `sum_r2_weak`);
            } else if (round === 3) {
                // READ THE EVIDENCE — update honestly under mixed signals. Common Errors 3 & 5.
                if (d.evidence === `honest`) {
                    resolvedDelta += 14; convictionDelta += 16; optionDelta += 6; coachKey = `coach_r3_honest`;
                } else if (d.evidence === `cherrypick`) {
                    // Hearing only the engagement, ignoring the price signal (confirmation).
                    resolvedDelta -= 4; convictionDelta -= 14; coachKey = `coach_r3_cherrypick`;
                } else if (d.evidence === `abandon`) {
                    // Over-reaction to one negative signal throws away real option value.
                    resolvedDelta += 4; convictionDelta -= 6; optionDelta -= 12; coachKey = `coach_r3_abandon`;
                } else if (d.evidence === `invent`) {
                    // Manufacturing a 65% probability — false precision on genuine uncertainty.
                    convictionDelta -= 16; ds.falsePrecision = true; coachKey = `coach_r3_invent`;
                }

                if (d.optionset === `staged`) {
                    optionDelta += 12; convictionDelta += 8; coachKey = (d.evidence === `honest`) ? `coach_r3_staged` : coachKey;
                } else if (d.optionset === `commitnow`) {
                    // Premature commitment on still-mixed evidence (Common Error 2).
                    optionDelta -= 14; convictionDelta -= 10; coachKey = `coach_r3_commitnow`;
                } else if (d.optionset === `probeagain`) {
                    // One more SHARP probe is fine early; but it costs money and time.
                    spend += 0.30; weeksUsed += 8; resolvedDelta += 8;
                    if (ds.monthsLeft <= 4) { optionDelta -= 8; convictionDelta -= 6; ds.forcedParalysis = true; coachKey = `coach_r3_probeagain_late`; }
                    else { coachKey = `coach_r3_probeagain_ok`; }
                } else if (d.optionset === `shelve`) {
                    optionDelta -= 18; convictionDelta -= 8; coachKey = `coach_r3_shelve`;
                }

                // Honest residual-uncertainty estimate: a calibrated team neither claims certainty
                // (false precision) nor pretends nothing was learned.
                if (d.remaining >= 30 && d.remaining <= 65) { convictionDelta += 8; }
                else if (d.remaining <= 10) { convictionDelta -= 8; ds.falsePrecision = true; coachKey = `coach_r3_overcertain`; }
                else if (d.remaining >= 90) { convictionDelta -= 6; coachKey = `coach_r3_undersold`; }

                summaryKey = (d.evidence === `honest` && d.optionset === `staged`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // WHEN TO COMMIT — frontier thinking. Commit when enough uncertainty is resolved
                // and before the window shuts; staged + triggered preserves optionality.
                if (d.timing === `stagednow`) {
                    convictionDelta += 16; optionDelta += 6; coachKey = `coach_r4_stagednow`;
                    ds.committed = `staged`;
                } else if (d.timing === `fullnow`) {
                    // Premature full commitment if uncertainty is still high (Common Error 2).
                    ds.committed = `full`;
                    if (ds.resolved < 55) { convictionDelta -= 16; optionDelta -= 12; coachKey = `coach_r4_fullnow_early`; }
                    else { convictionDelta += 2; coachKey = `coach_r4_fullnow_ok`; }
                } else if (d.timing === `waitmore`) {
                    // Waiting for certainty: the option erodes and talent walks (Common Error 1 & 5).
                    ds.committed = `wait`; optionDelta -= 20; convictionDelta -= 14; ds.forcedParalysis = true;
                    weeksUsed += 26; coachKey = `coach_r4_wait`;
                } else if (d.timing === `walkaway`) {
                    ds.committed = `walk`; optionDelta -= 14; convictionDelta -= 6; coachKey = `coach_r4_walkaway`;
                }

                // Sizing: small/medium staged bets fit the resolved evidence; full now is oversized.
                if (d.size === `small` || d.size === `medium`) {
                    if (d.timing === `stagednow`) { convictionDelta += 8; optionDelta += 4; }
                } else if (d.size === `full`) {
                    if (ds.resolved < 60) { convictionDelta -= 10; optionDelta -= 8; coachKey = `coach_r4_oversized`; }
                } else if (d.size === `none`) {
                    if (d.timing !== `walkaway`) { convictionDelta -= 6; }
                }

                // Trigger conditions: a measurable milestone + a competitor-deadline is what makes a
                // commitment timed rather than hoped.
                if (d.trigger === `paymilestone`) { convictionDelta += 10; optionDelta += 4; }
                else if (d.trigger === `gutfeel`) { convictionDelta -= 8; coachKey = (coachKey === `coach_r4_stagednow`) ? `coach_r4_notrigger` : coachKey; }
                else if (d.trigger === `boardask`) { convictionDelta -= 4; }

                // Standing behind judgement under acknowledged uncertainty (Furr's "sustain").
                convictionDelta += Math.round((d.stand - 60) / 8);

                summaryKey = (d.timing === `stagednow` && (d.size === `small` || d.size === `medium`) && d.trigger === `paymilestone`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply spend and time consumption.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            if (ds.budgetUsed > this.BUDGET_CAP) ds.budgetUsed = this.BUDGET_CAP;
            ds.monthsLeft = Math.max(0, Math.round((ds.monthsLeft - weeksUsed / 4.33) * 10) / 10);

            // Runway pressure: as months evaporate, holding option value gets harder; if you have
            // already burned the runway, the option erodes on its own (talent loss, rival lock-in).
            if (ds.monthsLeft <= 2 && round >= 3) { optionDelta -= 6; }

            // Apply deltas with clamps.
            ds.resolved = Math.max(0, Math.min(100, ds.resolved + resolvedDelta));
            ds.option = Math.max(0, Math.min(100, ds.option + optionDelta));
            ds.conviction = Math.max(0, Math.min(100, ds.conviction + convictionDelta));

            ds.resolvedHistory.push(Math.round(ds.resolved));
            ds.optionHistory.push(Math.round(ds.option));
            ds.convictionHistory.push(Math.round(ds.conviction));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            var res = {
                period: state.currentPeriod,
                resolved: Math.round(ds.resolved),
                resolvedDelta: Math.round(resolvedDelta),
                option: Math.round(ds.option),
                optionDelta: Math.round(optionDelta),
                conviction: Math.round(ds.conviction),
                convictionDelta: Math.round(convictionDelta),
                budgetUsed: ds.budgetUsed,
                monthsLeft: ds.monthsLeft,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

