        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.resolvedHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                frontierChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.resolvedHistory },
                        { data: ds.optionHistory },
                        { data: ds.convictionHistory }
                    ]
                }
