        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var resolved = Math.round(ds.resolved || 0), option = Math.round(ds.option || 0), conviction = Math.round(ds.conviction || 0);
            return Math.max(0, Math.min(100, Math.round(resolved * 0.3 + option * 0.3 + conviction * 0.4)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const resolved = Math.round(ds.resolved), option = Math.round(ds.option), conviction = Math.round(ds.conviction);
            const monthsLeft = ds.monthsLeft;

            // The frontier outcome: enough uncertainty resolved, option preserved, and a high-quality,
            // evidence-based, well-timed judgement — without false precision or a sunk-cost trap.
            const learnedEnough = resolved >= 55;
            const optionLive = option >= 50;
            const goodJudgement = conviction >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_paralysed`;
            if (learnedEnough && optionLive && goodJudgement && composite >= 72) performanceKey = `grade_embraced`;
            else if (learnedEnough && goodJudgement && composite >= 58) performanceKey = `grade_welltimed`;
            else if (ds.committed === `full` && ds.resolved < 55) performanceKey = `grade_early`;
            else if (ds.forcedParalysis || ds.committed === `wait`) performanceKey = `grade_waited`;
            else if (ds.falsePrecision && composite < 55) performanceKey = `grade_false`;
            else if (composite >= 45) performanceKey = `grade_partial`;
            const performance = T(performanceKey);

            const insights = [];
            if (learnedEnough && optionLive && goodJudgement) insights.push(window.mySimulation.t(`insight_frontier`));
            else if (ds.committed === `full` && ds.resolved < 55) insights.push(window.mySimulation.t(`insight_early`));
            else if (ds.committed === `wait` || ds.forcedParalysis) insights.push(window.mySimulation.t(`insight_waited`));
            else if (ds.falsePrecision) insights.push(window.mySimulation.t(`insight_falseprecision`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (ds.bigbuildLocked) insights.push(window.mySimulation.t(`insight_sunkcost`));
            if (option < 40) insights.push(window.mySimulation.t(`insight_optionlost`));
            if (resolved < 45) insights.push(window.mySimulation.t(`insight_stillfoggy`));
            if (learnedEnough && optionLive && goodJudgement && monthsLeft >= 1) insights.push(window.mySimulation.t(`insight_runway`));

            return {
                resolved: resolved,
                option: option,
                conviction: conviction,
                monthsLeft: monthsLeft,
                budgetUsed: ds.budgetUsed,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="eu-cm-metric"><span class="eu-cm-mv">' + Math.round(s.resolved||0) + '</span><span class="eu-cm-ml">' + T('cm_m_resolved') + '</span></div>'
                + '<div class="eu-cm-metric"><span class="eu-cm-mv">' + Math.round(s.option||0) + '</span><span class="eu-cm-ml">' + T('cm_m_option') + '</span></div>'
                + '<div class="eu-cm-metric"><span class="eu-cm-mv">' + Math.round(s.conviction||0) + '</span><span class="eu-cm-ml">' + T('cm_m_conviction') + '</span></div>'
                + '<div class="eu-cm-metric"><span class="eu-cm-mv">' + Math.round(s.monthsLeft||0) + '</span><span class="eu-cm-ml">' + T('cm_m_months') + '</span></div>';
            return ''
                + '<div class="eu-completion">'
                +   '<div class="eu-cm-head">'
                +     '<div class="eu-cm-score">' + score + '<span class="eu-cm-score-max">/100</span></div>'
                +     '<div class="eu-cm-grade">' + grade + '</div>'
                +   '</div>'
                +   '<div class="eu-cm-metrics">' + metrics + '</div>'
                +   '<div class="eu-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="eu-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.falsePrecision) return window.mySimulation.t(`hint_falseprecision`);
            if (ds.bigbuildLocked) return window.mySimulation.t(`hint_sunkcost`);
            if (ds.option < 35) return window.mySimulation.t(`hint_option`);
            if (ds.monthsLeft <= 3 && state.currentPeriod < 4) return window.mySimulation.t(`hint_runway`);
            if (ds.resolved < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_resolve`);
            if (ds.resolved >= 55 && ds.option >= 50 && ds.conviction >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

